<?php $h = [PeoplePublic::class, 'h']; ?>
<main id="archive-main" class="people-public bio-directory" tabindex="-1"><div id="main-content" class="bio-container" tabindex="-1">
    <nav class="bio-breadcrumb" aria-label="Breadcrumb"><ol><li><a href="<?= SITE_URL ?>">The collection</a></li><li><?= PeoplePublic::icon('chevron-right') ?><span aria-current="page">People</span></li></ol></nav>
    <header class="bio-directory-heading"><div><h1>People &amp; biographies</h1><p>Discover the lives connected to the stamps, covers, and records in this collection.</p></div><span class="bio-directory-count"><?= number_format($view['total']) ?> <?= $view['total'] === 1 ? 'biography' : 'biographies' ?><?= $view['query'] !== '' || $view['letter'] !== '' ? ' found' : '' ?></span></header>
    <section class="bio-browse" aria-label="Find a biography">
        <form class="bio-search" method="get" action="<?= SITE_URL ?>/people.php" role="search"><label class="bio-search-field"><?= PeoplePublic::icon('magnifying-glass') ?><span class="bio-sr-only">Search biographies</span><input type="search" name="q" value="<?= $h($view['query']) ?>" placeholder="Search by name, subject, or story" maxlength="150"></label><?php if ($view['letter'] !== ''): ?><input type="hidden" name="letter" value="<?= $h($view['letter']) ?>"><?php endif; ?><button class="bio-button bio-button-primary" type="submit">Search</button></form>
        <nav class="bio-alphabet" aria-label="Browse biographies by first letter"><a href="<?= $h(PeoplePublic::directoryUrl($view, ['letter' => '', 'page' => 1])) ?>" <?= $view['letter'] === '' ? 'aria-current="page"' : '' ?>>All</a><?php foreach (array_merge(range('A', 'Z'), ['#']) as $letter): ?><a href="<?= $h(PeoplePublic::directoryUrl($view, ['letter' => $letter, 'page' => 1])) ?>" <?= $letter === $view['letter'] ? 'aria-current="page"' : '' ?> <?= $letter === '#' ? 'aria-label="Names beginning with numbers or other characters"' : '' ?>><?= $letter ?></a><?php endforeach; ?></nav>
    </section>
    <?php if ($view['query'] !== '' || $view['letter'] !== ''): ?><div class="bio-filter-summary"><p><?= $view['query'] !== '' ? 'Results for “' . $h($view['query']) . '”' : 'Browsing names' ?><?= $view['letter'] !== '' ? ' · ' . $h($view['letter']) : '' ?></p><a href="<?= SITE_URL ?>/people.php">Clear filters</a></div><?php endif; ?>
    <?php if ($view['people']): ?><div class="bio-person-grid"><?php foreach ($view['people'] as $profile): $portrait = PeopleSupport::imageUrl($profile['profile_image']); ?>
        <a class="bio-person" href="<?= SITE_URL ?>/person/<?= rawurlencode($profile['slug']) ?>"><div class="bio-person-image"><?php if ($portrait): ?><img src="<?= $h($portrait) ?>" alt="Portrait of <?= $h($profile['name']) ?>" loading="lazy" width="540" height="620"><?php else: ?><span class="bio-initials" aria-hidden="true"><?= $h(PeoplePublic::initials($profile['name'])) ?></span><?php endif; ?></div><div class="bio-person-copy"><h2><?= $h($profile['name']) ?></h2><?php if ($dates = PeoplePublic::lifespan($profile)): ?><p class="bio-person-dates"><?= $h($dates) ?></p><?php endif; ?><?php if ($profile['short_description']): ?><p class="bio-person-description"><?= $h($profile['short_description']) ?></p><?php endif; ?><span class="bio-person-footer"><span><?= (int)$profile['record_count'] ?> collection <?= (int)$profile['record_count'] === 1 ? 'record' : 'records' ?></span><span class="bio-person-read">Read biography <?= PeoplePublic::icon('arrow-right') ?></span></span></div></a>
    <?php endforeach; ?></div>
    <?php if ($view['pages'] > 1): ?><nav class="bio-pagination" aria-label="Biography pages"><p>Page <?= $view['page'] ?> of <?= $view['pages'] ?></p><div><?php if ($view['page'] > 1): ?><a class="bio-button" href="<?= $h(PeoplePublic::directoryUrl($view, ['page' => $view['page'] - 1])) ?>">Previous</a><?php endif; ?><?php for ($number = max(1, $view['page'] - 2); $number <= min($view['pages'], $view['page'] + 2); $number++): ?><a class="bio-page-number" href="<?= $h(PeoplePublic::directoryUrl($view, ['page' => $number])) ?>" <?= $number === $view['page'] ? 'aria-current="page"' : '' ?> aria-label="Page <?= $number ?>"><?= $number ?></a><?php endfor; ?><?php if ($view['page'] < $view['pages']): ?><a class="bio-button" href="<?= $h(PeoplePublic::directoryUrl($view, ['page' => $view['page'] + 1])) ?>">Next</a><?php endif; ?></div></nav><?php endif; ?>
    <?php else: ?><section class="bio-empty" aria-labelledby="bio-empty-title"><span aria-hidden="true"><?= PeoplePublic::icon('book-open') ?></span><h2 id="bio-empty-title"><?= $view['query'] !== '' || $view['letter'] !== '' ? 'No matching biographies' : 'Stories are being collected' ?></h2><p><?= $view['query'] !== '' || $view['letter'] !== '' ? 'Try another name or keyword, or clear your filters to browse all biographies.' : 'Public biographies will appear here as they are added to the archive.' ?></p><?php if ($view['query'] !== '' || $view['letter'] !== ''): ?><a class="bio-button" href="<?= SITE_URL ?>/people.php">Browse all biographies</a><?php endif; ?></section><?php endif; ?>
</div></main>
